<?php
// Private agenda: no team tasks, support tickets, reports or delegated ownership.
function agendaNow(){return (new DateTimeImmutable('now',new DateTimeZone('America/Lima')))->format('Y-m-d H:i:s');}
function agendaPayload($p){
 $title=$p['Titulo']??'';$detail=$p['Detalle']??'';if(!is_string($title)||!trim($title)||mb_strlen($title)>180||!is_string($detail)||mb_strlen($detail)>5000)throw new InvalidArgumentException('Escribe una tarea de hasta 180 caracteres y un detalle de hasta 5000.');
 $remind=$p['Recordar']??false;if(!in_array($remind,[true,false,0,1,'0','1'],true))throw new InvalidArgumentException('Opción de aviso no válida.');$remind=(int)(bool)$remind;
 $date=array_key_exists('Fecha',$p)?str_replace('T',' ',(string)$p['Fecha']):agendaNow();if(strlen($date)===16)$date.=':00';$d=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$date,new DateTimeZone('America/Lima'));if(!$d||$d->format('Y-m-d H:i:s')!==$date)throw new InvalidArgumentException('Revisa la fecha y hora del aviso.');
 $before=filter_var($p['Anticipacion']??0,FILTER_VALIDATE_INT);$frequency=filter_var($p['Frecuencia']??15,FILTER_VALIDATE_INT);$repeat=$p['Repeticion']??'ninguna';if($before===false||$before<0||$before>1440||$frequency===false||$frequency<1||$frequency>1440||!in_array($repeat,['ninguna','diaria','semanal'],true))throw new InvalidArgumentException('Revisa cuándo avisar y cada cuántos minutos repetir.');
 return [trim($title),trim($detail),$date,$before,$frequency,$remind?$repeat:'ninguna',$remind];
}
return function($app){
 $auth=function($q,$r,$next){$db=$this->db;try{
  if(session_status()!==PHP_SESSION_ACTIVE)session_start();$user=$_SESSION['user']??'';if(!$user||(isset($_SESSION['expire'])&&$_SESSION['expire']<time())){session_write_close();return $r->withJson(['error'=>'Inicia sesión para abrir tu diario personal.'],401);}
  $_SESSION['agenda_csrf']=$_SESSION['agenda_csrf']??bin2hex(random_bytes(24));$csrf=$_SESSION['agenda_csrf'];session_write_close();$s=$db->prepare('SELECT Usuario FROM Seg_Usuario WHERE Usuario=? AND COALESCE(Anulado,0)=0');$s->execute([$user]);if(!$s->fetchColumn())return $r->withJson(['error'=>'Usuario no disponible.'],403);
  if($q->getMethod()!=='GET'&&!hash_equals($csrf,$q->getHeaderLine('X-Agenda-CSRF')))return $r->withJson(['error'=>'Actualiza la página antes de guardar.'],403);
  return $next($q->withAttribute('agenda',['user'=>$user,'csrf'=>$csrf]),$r)->withHeader('Cache-Control','no-store, private');
 }catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();return $r->withJson(['error'=>$e->getMessage()],422);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('[AGENDA] '.$e->getMessage());return $r->withJson(['error'=>'No se pudo guardar. Tu texto permanece en el diario; vuelve a intentarlo.'],500);}};
 $app->get('/agenda/contexto',function($q,$r){$i=$q->getAttribute('agenda');return $r->withJson($i+['ahora'=>agendaNow(),'zona'=>'America/Lima']);})->add($auth);
 $app->get('/agenda/notas',function($q,$r){$i=$q->getAttribute('agenda');$s=$this->db->prepare("SELECT * FROM Rhu_DiarioPersonal WHERE Usuario=? AND Estado<>'cancelada' ORDER BY (Estado='pendiente') DESC,(Recordar=1) DESC,Fecha ASC,Id DESC LIMIT 1001");$s->execute([$i['user']]);$items=$s->fetchAll(PDO::FETCH_ASSOC);$limited=count($items)>1000;if($limited)array_pop($items);return $r->withJson(['notas'=>$items,'limitado'=>$limited]);})->add($auth);
 $app->get('/agenda/avisos',function($q,$r){$i=$q->getAttribute('agenda');$now=agendaNow();$s=$this->db->prepare("SELECT * FROM Rhu_DiarioPersonal WHERE Usuario=? AND Estado='pendiente' AND Recordar=1 AND Fecha<=DATE_ADD(?,INTERVAL Anticipacion MINUTE) ORDER BY Fecha,Id LIMIT 20");$s->execute([$i['user'],$now]);return $r->withJson(['notas'=>$s->fetchAll(PDO::FETCH_ASSOC),'ahora'=>$now]);})->add($auth);
 $app->post('/agenda/notas',function($q,$r){$i=$q->getAttribute('agenda');$values=agendaPayload($q->getParsedBody()?:[]);$s=$this->db->prepare('INSERT INTO Rhu_DiarioPersonal(Titulo,Detalle,Fecha,Anticipacion,Frecuencia,Repeticion,Recordar,Usuario) VALUES(?,?,?,?,?,?,?,?)');$s->execute(array_merge($values,[$i['user']]));return $r->withJson(['Id'=>(int)$this->db->lastInsertId()]);})->add($auth);
 $app->post('/agenda/notas/{id:[0-9]+}',function($q,$r,$args){$db=$this->db;$i=$q->getAttribute('agenda');$p=$q->getParsedBody()?:[];$db->beginTransaction();$s=$db->prepare('SELECT * FROM Rhu_DiarioPersonal WHERE Id=? AND Usuario=? FOR UPDATE');$s->execute([(int)$args['id'],$i['user']]);$t=$s->fetch(PDO::FETCH_ASSOC);if(!$t){$db->rollBack();return $r->withJson(['error'=>'Nota no disponible en tu diario.'],404);}if((int)($p['Version']??0)!==(int)$t['Version']){$db->rollBack();return $r->withJson(['error'=>'La nota cambió en otra ventana. Actualiza el diario para continuar.'],409);}
  $action=$p['accion']??'';$next=null;
  if($action==='reabrir'&&$t['Estado']==='concluida'&&$t['Repeticion']==='ninguna'){$s=$db->prepare("UPDATE Rhu_DiarioPersonal SET Estado='pendiente',Version=Version+1 WHERE Id=? AND Usuario=?");$s->execute([$t['Id'],$i['user']]);}
  elseif($t['Estado']!=='pendiente')throw new InvalidArgumentException('Esta nota ya está cerrada.');
  elseif($action==='editar'){$s=$db->prepare('UPDATE Rhu_DiarioPersonal SET Titulo=?,Detalle=?,Fecha=?,Anticipacion=?,Frecuencia=?,Repeticion=?,Recordar=?,Version=Version+1 WHERE Id=? AND Usuario=?');$s->execute(array_merge(agendaPayload($p),[$t['Id'],$i['user']]));}
  elseif(in_array($action,['concluir','cancelar'],true)){$s=$db->prepare('UPDATE Rhu_DiarioPersonal SET Estado=?,Version=Version+1 WHERE Id=? AND Usuario=?');$s->execute([$action==='concluir'?'concluida':'cancelada',$t['Id'],$i['user']]);if($action==='concluir'&&$t['Repeticion']!=='ninguna'){$date=new DateTimeImmutable($t['Fecha'],new DateTimeZone('America/Lima'));$now=new DateTimeImmutable(agendaNow(),new DateTimeZone('America/Lima'));do{$date=$date->modify($t['Repeticion']==='diaria'?'+1 day':'+1 week');}while($date<=$now);$s=$db->prepare('INSERT INTO Rhu_DiarioPersonal(Titulo,Detalle,Fecha,Anticipacion,Frecuencia,Repeticion,Recordar,Usuario,Anterior) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$t['Titulo'],$t['Detalle'],$date->format('Y-m-d H:i:s'),$t['Anticipacion'],$t['Frecuencia'],$t['Repeticion'],$t['Recordar'],$i['user'],$t['Id']]);$next=(int)$db->lastInsertId();}}
  else throw new InvalidArgumentException('Acción no disponible.');$db->commit();return $r->withJson(['ok'=>true,'siguiente'=>$next]);
 })->add($auth);
};
